import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"紀元区分総表","description":"","frontmatter":{},"headers":[],"relativePath":"ja/70-纪元划分总表.md","filePath":"ja/70-纪元划分总表.md","lastUpdated":1789183869000}'),l={name:"ja/70-纪元划分总表.md"};function i(h,t,o,n,s,b){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="紀元区分総表" tabindex="-1">紀元区分総表 <a class="header-anchor" href="#紀元区分総表" aria-label="Permalink to &quot;紀元区分総表&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>70</td></tr><tr><td>所属モジュール</td><td>歴史紀元と重大事件</td></tr><tr><td>コアキーワード</td><td>紀元区分、歴史分期、四段階昇維、タイムライン、マイルストーン</td></tr></tbody></table><h2 id="第一節-紀元区分の基本原則" tabindex="-1">第一節 紀元区分の基本原則 <a class="header-anchor" href="#第一節-紀元区分の基本原則" aria-label="Permalink to &quot;第一節 紀元区分の基本原則&quot;">​</a></h2><p>衡元宙の歴史紀元区分は四段階昇維経路を根本的枠組みとし、アンカーメカニズムの発展状態を核心的な分期根拠とする。各紀元は文明と宇宙の関係における一回の根本的な変革に対応し、紀元間の境界は任意の時間节点ではなく、宇宙級の意義を持つ重大事件によって標定される。</p><p>紀元区分は三つの原則に従う:</p><ul><li><strong>昇維対応原則</strong>: 各大紀元は四段階昇維経路における一つの段階に対応し、紀元内部の細分期間は当該段階内の重要な進展に対応する</li><li><strong>事件標定原則</strong>: 紀元の起止点は標識的な重大事件によって確定され、単純な時間等分によるものではない</li><li><strong>文明状態原則</strong>: 各紀元は当該時期の文明の核心的特徴によって命名され、当時の主要矛盾と発展方向を反映する</li></ul><h2 id="第二節-衡元宙歴史紀元総表" tabindex="-1">第二節 衡元宙歴史紀元総表 <a class="header-anchor" href="#第二節-衡元宙歴史紀元総表" aria-label="Permalink to &quot;第二節 衡元宙歴史紀元総表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>紀元番号</th><th>紀元名称</th><th>対応昇維段階</th><th>起止標識事件</th><th>核心的特徴</th></tr></thead><tbody><tr><td>第一紀元</td><td>前アンカー時代</td><td>昇維前</td><td>宇宙誕生→初代アンカー覚醒</td><td>略奪式修錬が主導、文明断層が頻発</td></tr><tr><td>第二紀元</td><td>アンカー覚醒紀元</td><td>現実筑基起動</td><td>初代アンカー覚醒→共生憲章調印</td><td>アンカーメカニズム確立、反略奪思想の萌芽</td></tr><tr><td>第三紀元</td><td>共生体系確立期</td><td>現実筑基</td><td>共生憲章調印→三百套体系全面開放</td><td>共生制度落地、社会再構築完了</td></tr><tr><td>第四紀元</td><td>体系開放と活性化紀元</td><td>科技賦能起動</td><td>三百套体系開放→20%活性化戦略完了</td><td>修錬普及、法則工学技術の突破</td></tr><tr><td>第五紀元</td><td>初回昇維紀元</td><td>科技賦能→意識進化</td><td>初回昇維成功→万族共和成立</td><td>文明昇維検証、意識域インターフェース突破</td></tr><tr><td>第六紀元</td><td>万族共和紀元</td><td>意識進化</td><td>万族共和成立→位面間探索起動</td><td>万族制度統一、集団意識共生</td></tr><tr><td>第七紀元</td><td>位面間探索紀元</td><td>意識進化→星際共生</td><td>位面間探索起動→星際ネットワーク初步建成</td><td>位面大発見、アンカーネットワーク拡張</td></tr><tr><td>第八紀元</td><td>星際共生時代</td><td>星際共生</td><td>星際ネットワーク建成→宇宙全体昇維</td><td>万族宇宙共生、宇宙昇維進行中</td></tr></tbody></table><h2 id="第三節-各紀元の時間跨度と重要指標" tabindex="-1">第三節 各紀元の時間跨度と重要指標 <a class="header-anchor" href="#第三節-各紀元の時間跨度と重要指標" aria-label="Permalink to &quot;第三節 各紀元の時間跨度と重要指標&quot;">​</a></h2><p>衡元宙は複数の位面を含むため、異なる位面では時間の流速に差があり、紀元の時間跨度は主位面標準時間を基準とする:</p><table tabindex="0"><thead><tr><th>紀元</th><th>予估時間跨度</th><th>アンカーカバー率</th><th>修錬者比例</th><th>共生度指数</th></tr></thead><tbody><tr><td>前アンカー時代</td><td>不考（数十億年量级）</td><td>0%</td><td>&lt;0.01%</td><td>&lt;10</td></tr><tr><td>アンカー覚醒紀元</td><td>数千年</td><td>1%→10%</td><td>0.01%→1%</td><td>10→30</td></tr><tr><td>共生体系確立期</td><td>数百年</td><td>10%→40%</td><td>1%→10%</td><td>30→50</td></tr><tr><td>体系開放と活性化紀元</td><td>数百年</td><td>40%→70%</td><td>10%→30%</td><td>50→70</td></tr><tr><td>初回昇維紀元</td><td>数十年</td><td>70%→85%</td><td>30%→50%</td><td>70→80</td></tr><tr><td>万族共和紀元</td><td>数百年</td><td>85%→95%</td><td>50%→70%</td><td>80→90</td></tr><tr><td>位面間探索紀元</td><td>数千年</td><td>95%→99%</td><td>70%→90%</td><td>90→95</td></tr><tr><td>星際共生時代</td><td>継続中</td><td>→100%</td><td>→100%</td><td>→100</td></tr></tbody></table><p>アンカーカバー率とはアンカーハードウェアが配備された位面子区域の占比を指す；修錬者比例とは正規修錬体系がカバーする生命の比例を指す；共生度指数は文明の共生程度を測る総合指標で、満点は100である。</p><h2 id="第四節-紀元演進の内在的論理" tabindex="-1">第四節 紀元演進の内在的論理 <a class="header-anchor" href="#第四節-紀元演進の内在的論理" aria-label="Permalink to &quot;第四節 紀元演進の内在的論理&quot;">​</a></h2><p>衡元宙の紀元演進は線形的な時間の流れではなく、螺旋上昇的な進化過程である。各紀元は前の紀元が残した核心的な矛盾を解決すると同時に、次の紀元の発展条件を醸成する:</p><ul><li>前アンカー時代の根本的な矛盾は略奪と共生の矛盾であり、その極端化がアンカー覚醒の必然性をもたらした</li><li>アンカー覚醒紀元は「アンカーが存在するか否か」の問題を解決したが、「アンカーが誰のために奉仕するか」の制度的挑戦に直面した</li><li>共生体系確立期は制度構築を完了したが、修錬資源の独占が依然として大衆の進化を制約している</li><li>体系開放と活性化紀元は修錬独占を打破したが、個体能力の跳躍が新たな倫理と安全の挑戦をもたらした</li><li>初回昇維紀元は昇維の実行可能性を検証したが、単一位面の昇維は宇宙全体の進化を推進するには不十分である</li><li>万族共和紀元は文明制度を統一したが、宇宙には依然として大量の未接触位面と種族が存在する</li><li>位面間探索紀元は文明の境界を拡張したが、分散した位面はより緊密な星際的な接続を必要とする</li><li>星際共生時代は最終的に宇宙全体昇維の究極目標に指向する</li></ul><h2 id="第五節-現在の紀元の位置付け" tabindex="-1">第五節 現在の紀元の位置付け <a class="header-anchor" href="#第五節-現在の紀元の位置付け" aria-label="Permalink to &quot;第五節 現在の紀元の位置付け&quot;">​</a></h2><p>衡元宙の現在の発展状態によると、文明は第三紀元（共生体系確立期）から第四紀元（体系開放と活性化紀元）への過渡的な重要节点にある。共生制度はすでに主要位面で落地し、三百套体系の開放作業が全面的に推進されており、20%活性化戦略が実施段階に入っている。法則工学層の複数の核心技術（増倍果実推演エンジン、空間法則装置、複製鏡システム）は実験室から量産に移行している。</p><p>この過渡期の核心的任務は: 三百套体系の開放が真に衆生に恩恵をもたらすことを確保すると同時に、20%活性化戦略を通じて第一批の位面至高強者を養成し、初回昇維のために十分なエネルギーと経験を蓄積することである。</p><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>紀元区分総表は衡元宙の歴史演進を理解するためのマクロ的枠組みである。それは宇宙の長い歴史を八つの明確な内在的論理を持つ紀元に濃縮し、各紀元は宇宙全体昇維への必要な階梯である。後続の各文書は各紀元とその中の重大事件について詳細に展開する。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>71-前アンカー時代</li><li>72-アンカー覚醒紀元</li><li>76-初回昇維マイルストーン</li></ul>',22)])])}const p=d(l,[["render",i]]);export{_ as __pageData,p as default};
